class stringx
{
public:
  stringx();
  stringx(const stringx&);
  ~stringx();
};

stringx operator+(const stringx&, const char*);
void error(const stringx&);

class script_object
{
public:
  const stringx& get_name() const;
};

class vm_executable
{
public:
  const stringx& get_fullname() const;
};

class vm_thread
{
public:
  script_object* get_instance() const;
  vm_executable* get_executable() const;
};

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
public:
  char* get_SP() const { return SP; }
  void pop(int n) { SP -= n; }
  bool push(const char*, int);
  vm_thread* get_thread() const { return my_thread; }
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

class vector3d
{
public:
  float x, y, z;
};

template<class T>
class vector
{
public:
  class iterator
  {
  public:
    T* node;
    iterator& operator--() { --node; return *this; }
  };
  T* start;
  T* finish;
  T* end_of_storage;
  iterator begin() { iterator i = { start }; return i; }
};

typedef vector<vector3d> vector3d_list;
typedef vector3d_list* vm_vector3d_list_t;
typedef vector3d_list::iterator vm_vector3d_list_iterator_t;

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()

#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() )

#define SLF_DONE \
  return true

class slf_vector3d_list_rend_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vm_vector3d_list_t me;
  };
  virtual bool operator()(vm_stack& stack,entry_t entry);
};

bool slf_vector3d_list_rend_t::operator()(vm_stack& stack,entry_t entry)
{
  SLF_PARMS;
  vm_vector3d_list_iterator_t result = parms->me->begin();
  --result;
  SLF_RETURN;
  SLF_DONE;
}
